text:
{
  "design": {
    "theme": "chalk",
    "picture_style": "illustration"
  },
  "flow": [
    {
      "slide": 1,
      "does": "Recall family relationships",
      "look_at": {
        "kind": "picture",
        "shows": "A family with two children, their parents and grandparents"
      },
      "teaches": []
    },
    {
      "slide": 2,
      "does": "Introduce the approved objectives",
      "look_at": {
        "kind": "none",
        "shows": null
      },
      "teaches": []
    },
    {
      "slide": 3,
      "does": "Teach family nouns and possessives",
      "look_at": {
        "kind": "diagram",
        "shows": "Six family phrases grouped with their English meanings"
      },
      "teaches": [1]
    },
    {
      "slide": 4,
      "does": "Check noun-based possessive choice",
      "look_at": {
        "kind": "none",
        "shows": null
      },
      "teaches": [1]
    },
    {
      "slide": 5,
      "does": "Model name, age and personality",
      "look_at": {
        "kind": "picture",
        "shows": "An imaginary sister whose details appear in the slide text"
      },
      "teaches": [2]
    },
    {
      "slide": 6,
      "does": "Try a parallel description",
      "look_at": {
        "kind": "none",
        "shows": null
      },
      "teaches": [2]
    },
    {
      "slide": 7,
      "does": "Correct adjective-agreement misconceptions",
      "look_at": {
        "kind": "none",
        "shows": null
      },
      "teaches": [2]
    },
    {
      "slide": 8,
      "does": "Teach siblings and negative statements",
      "look_at": {
        "kind": "none",
        "shows": null
      },
      "teaches": [3]
    },
    {
      "slide": 9,
      "does": "Model a complete family paragraph",
      "look_at": {
        "kind": "picture",
        "shows": "A narrator with one brother and no sister"
      },
      "teaches": [1, 2, 3]
    },
    {
      "slide": 10,
      "does": "Write a near-identical family paragraph",
      "look_at": {
        "kind": "none",
        "shows": null
      },
      "teaches": [1, 2, 3]
    },
    {
      "slide": 11,
      "does": "Apply the language to a chosen family",
      "look_at": {
        "kind": "none",
        "shows": null
      },
      "teaches": [1, 2, 3]
    }
  ],
  "title": {
    "template": "title",
    "heading": "Ma famille",
    "lead": "My family\nRepère les deux enfants. / Find the two children.\nWho are the other people in their family? Answer in English or French.",
    "picture": {
      "shows": "An illustrated family portrait with two children, their parents and their grandparents",
      "must_see": [
        "two school-age children",
        "two adult parents",
        "two older grandparents"
      ],
      "subject": "generic"
    }
  },
  "slides": [
    {
      "template": "visual-text",
      "heading": "Les membres de ma famille",
      "lead": "Mon, ma and mes mean “my”. Choose for the French noun, not the speaker.",
      "points": [
        {
          "label": "Singular",
          "text": "mon: masculine noun; ma: feminine noun"
        },
        {
          "label": "Plural",
          "text": "mes: more than one"
        }
      ],
      "figure": {
        "kind": "table",
        "shows": "The six required family phrases and their English meanings",
        "alt": "Mon père: my father; ma mère: my mother; mon frère: my brother; ma sœur: my sister; mes parents: my parents; mes grands-parents: my grandparents.",
        "title": null,
        "header": ["Français", "English"],
        "rows": [
          ["mon père", "father"],
          ["ma mère", "mother"],
          ["mon frère", "brother"],
          ["ma sœur", "sister"],
          ["mes parents", "parents"],
          ["mes grands-parents", "grandparents"]
        ]
      }
    },
    {
      "template": "hinge",
      "heading": "Choisis la bonne réponse",
      "stem": "Léa says “my brother”. Which phrase is correct?",
      "options": [
        "ma frère",
        "mon frère",
        "mes frère"
      ],
      "correct": 2
    },
    {
      "template": "visual-text",
      "heading": "Décrire une personne",
      "lead": "Ma sœur s’appelle Léa. Elle a treize ans. Elle est gentille.",
      "points": [
        "il / elle = he / she",
        "s’appelle = is called; a … ans = is … years old",
        "est = is; gentil / gentille = kind"
      ],
      "figure": {
        "shows": "An imaginary teenage sister smiling",
        "must_see": [
          "teenage girl",
          "friendly smile"
        ],
        "subject": "generic"
      }
    },
    {
      "template": "practice",
      "heading": "À toi : décris une sœur",
      "questions": [
        "Write “My sister is called Emma”.",
        "Write “She is fourteen years old”.",
        "Write “She is kind”."
      ],
      "instruction": "Écris en français. / Write in French. Use: ma sœur; s’appelle; elle; a; est; gentille. Fourteen = quatorze.",
      "picture": null
    },
    {
      "template": "compare",
      "heading": "L’adjectif change aussi",
      "columns": [
        {
          "label": "Il",
          "text": "Il est gentil. / He is kind.\nIl est amusant. / He is funny.\nUse these forms with mon frère or mon père.",
          "picture": null
        },
        {
          "label": "Elle",
          "text": "Elle est gentille. / She is kind.\nElle est amusante. / She is funny.\nNot “Elle est gentil”: gentil → gentille.",
          "picture": null
        }
      ]
    },
    {
      "template": "explain",
      "heading": "J’ai… / Je n’ai pas de…",
      "lead": "Use j’ai to say which siblings you have.",
      "points": [
        "J’ai un frère. / I have a brother.",
        "J’ai une sœur. / I have a sister.",
        "Je n’ai pas de sœur. / I don’t have a sister. Use de, not une."
      ]
    },
    {
      "template": "visual-text",
      "heading": "Un exemple complet",
      "lead": "J’ai un frère. Je n’ai pas de sœur. Mon frère s’appelle Hugo. Il a douze ans. Il est amusant.",
      "points": [
        "Siblings: one brother; no sister.",
        "Hugo: twelve years old; funny."
      ],
      "figure": {
        "shows": "An imaginary narrator standing beside their only sibling, a brother",
        "must_see": [
          "two school-age children",
          "boy beside narrator"
        ],
        "subject": "generic"
      }
    },
    {
      "template": "practice",
      "heading": "À toi : une autre famille",
      "questions": [
        "Write that you have one sister and no brother.",
        "Add: your sister is called Zoé; she is thirteen.",
        "Add: she is funny."
      ],
      "instruction": "Écris cinq phrases. / Write five sentences. Words: j’ai; une sœur; je n’ai pas de; frère; ma sœur; s’appelle; elle; a; treize ans; est; amusant / amusante.",
      "picture": null
    },
    {
      "template": "practice",
      "heading": "Présente ta famille",
      "questions": [
        "Choose a real or imaginary family. State which siblings you have and one you do not have.",
        "Describe one family member: relationship, name, age and one personality trait.",
        "Stretch: add a second family member with a different trait."
      ],
      "instruction": "Écris un petit paragraphe. / Write a short paragraph. Support: j’ai…; je n’ai pas de…; mon / ma / mes; il / elle s’appelle…; il / elle a… ans; il / elle est…",
      "picture": null
    }
  ]
}
